import json, csv, datetime
import pandas as pd

FIELD_MAP = {
    'user_id': 'user_id', 'id': 'user_id', 'userId': 'user_id',
    'email': 'email', 'email_address': 'email',
    'full_name': 'name', 'name': 'name', 'userName': 'name',
    'registration_date': 'created_date', 'created_at': 'created_date', 'joined': 'created_date',
    'status': 'status',
}
UNIFIED_FIELDS = ['name', 'email', 'created_date', 'status']


def norm_date(v):
    if v is None:
        return None
    s = str(v).strip()
    if s == '' or s.lower() == 'nan':
        return None
    for fmt in ('%Y-%m-%d', '%Y/%m/%d', '%m/%d/%Y', '%d-%m-%Y', '%Y-%m-%dT%H:%M:%S'):
        try:
            return datetime.datetime.strptime(s[:len(fmt)+4], fmt).strftime('%Y-%m-%d')
        except ValueError:
            continue
    try:
        return pd.to_datetime(s).strftime('%Y-%m-%d')
    except Exception:
        return s


def remap(rec):
    out = {}
    for k, v in rec.items():
        if k not in FIELD_MAP:
            continue
        uk = FIELD_MAP[k]
        if v is None:
            continue
        if isinstance(v, float) and pd.isna(v):
            continue
        if uk == 'created_date':
            v = norm_date(v)
        elif uk == 'user_id':
            v = int(v)
        else:
            v = str(v)
        if v is None or v == '':
            continue
        out[uk] = v
    return out


# Source A
with open('/data/source_a/users.json') as f:
    a = [remap(r) for r in json.load(f)]

# Source B
b = []
with open('/data/source_b/users.csv', newline='') as f:
    for r in csv.DictReader(f):
        b.append(remap(r))

# Source C
cdf = pd.read_parquet('/data/source_c/users.parquet')
c = [remap(r) for r in cdf.to_dict('records')]

sources = {'source_a': a, 'source_b': b, 'source_c': c}
PRIORITY = ['source_a', 'source_b', 'source_c']

# index by user_id per source
byid = {s: {r['user_id']: r for r in recs} for s, recs in sources.items()}
all_ids = sorted({uid for s in PRIORITY for uid in byid[s]})

merged = []
conflicts = []
for uid in all_ids:
    present = [(s, byid[s][uid]) for s in PRIORITY if uid in byid[s]]
    row = {'user_id': uid}
    for field in UNIFIED_FIELDS:
        vals = {}
        for s, rec in present:
            if field in rec:
                vals[s] = rec[field]
        if not vals:
            row[field] = None
            continue
        # selected = highest priority source that has the field
        for s in PRIORITY:
            if s in vals:
                selected = vals[s]
                break
        row[field] = selected
        distinct = set(vals.values())
        if len(distinct) > 1:
            conflicts.append({
                'user_id': uid,
                'field': field,
                'values': vals,
                'selected': selected,
            })
    merged.append(row)

out = pd.DataFrame(merged, columns=['user_id', 'name', 'email', 'created_date', 'status'])
out['user_id'] = out['user_id'].astype('int64')
for col in ['name', 'email', 'created_date', 'status']:
    out[col] = out[col].astype('object')
out.to_parquet('/app/merged_users.parquet', index=False)

report = {'total_conflicts': len(conflicts), 'conflicts': conflicts}
with open('/app/conflicts.json', 'w') as f:
    json.dump(report, f, indent=2)

print(out.to_string())
print('conflicts:', len(conflicts))
print(json.dumps(report, indent=2))

